(()=>{
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let page=0,current=null,loading=false;
const dialog=$('#user-editor'),form=$('#user-edit-form'),notice=$('#users-message');SOSProfile.mount($('#user-profile-fields'));
async function api(path,body){const r=await fetch(path,{cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json','X-SOS-Member':'1'},body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'Não foi possível concluir a operação.');return data}
async function load(){notice.textContent='Carregando usuários…';try{const data=await api('/api/admin/users?search='+encodeURIComponent($('#users-search').value.trim())+'&page='+page);$('#users-list').innerHTML=data.users.length?data.users.map(u=>`<article class="admin-row"><div class="details"><h3>${esc(u.name)}</h3><p>${esc(u.email)}</p><span class="visibility ${u.banned?'off':''}">${u.banned?'Banido':'Ativo'}</span></div><div class="row-actions"><button type="button" data-user-open="${esc(u.id)}">Dados, compras e avaliações</button></div></article>`).join(''):'<p class="empty">Nenhum usuário encontrado.</p>';$('#users-page').textContent=`${data.total} usuário(s) · Página ${page+1}`;$('#users-prev').disabled=page===0;$('#users-next').disabled=(page+1)*30>=data.total;notice.textContent=''}catch(e){notice.textContent=e.message}}
async function open(id){const [data,catalog]=await Promise.all([api('/api/admin/users/detail?id='+encodeURIComponent(id)),api('/api/catalog')]);current=data.user;form.reset();form.elements.email.value=current.email;SOSProfile.fill($('#user-profile-fields'),{...current.profile,fullName:current.profile.fullName||current.name});$('#user-editor-title').textContent=current.name;$('#user-status').textContent=current.banned?'Conta banida':'Conta ativa';$('#user-ban-reason').value=current.banReason;$('#user-ban-toggle').textContent=current.banned?'Reativar usuário':'Banir usuário';$('#user-edit-message').textContent='';$('#user-reviews').innerHTML=data.reviews.length?data.reviews.map(r=>`<article class="user-review"><a href="produto.html?id=${encodeURIComponent(r.productId)}" target="_blank" rel="noopener">Ver produto: ${esc(catalog.products.find(p=>p.id===r.productId)?.name||r.productId)}</a><p>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)} · ${r.demo?'Demonstração':'Compra verificada'}</p><p>${esc(r.text)}</p><small>${new Date(r.createdAt).toLocaleString('pt-BR')}</small></article>`).join(''):'<p>Este usuário ainda não publicou avaliações.</p>';renderUserOrders(data.orders);if(!dialog.open)dialog.showModal()}
function renderUserOrders(orders){const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);$('#user-orders').innerHTML=orders.length?orders.map(o=>`<article class="user-review"><h4>Pedido ${esc(o.id.slice(0,8))}</h4><p>${({pending:'Aguardando confirmação',completed:'Concluído',cancelled:'Cancelado'})[o.status]||esc(o.status)}${o.demo?' · Demonstração':''} · ${new Date(o.createdAt).toLocaleString('pt-BR')}</p><ul>${o.items.map(p=>`<li><a href="produto.html?id=${encodeURIComponent(p.id)}" target="_blank" rel="noopener">${p.quantity} × ${esc(p.name)}</a> — ${money(p.price*p.quantity)}</li>`).join('')}</ul><strong>Total dos produtos: ${money(o.total)}</strong></article>`).join(''):'<p>Este usuário ainda não fez pedidos.</p>'}
$('#users-search-form').onsubmit=e=>{e.preventDefault();page=0;load()};$('#users-prev').onclick=()=>{page--;load()};$('#users-next').onclick=()=>{page++;load()};$('[data-panel="users"]').addEventListener('click',load);$('#users-refresh').onclick=load;
$('#users-list').onclick=async e=>{const b=e.target.closest('[data-user-open]');if(b)try{await open(b.dataset.userOpen)}catch(err){notice.textContent=err.message}};
$('#user-close').onclick=()=>{if(!loading)dialog.close()};dialog.addEventListener('cancel',e=>{if(loading)e.preventDefault()});
function lock(value){loading=value;$('#user-save').disabled=value;$('#user-ban-toggle').disabled=value;$('#user-close').disabled=value}
form.onsubmit=async e=>{e.preventDefault();if(loading)return;lock(true);try{await api('/api/admin/users/update',{id:current.id,revision:current.revision,email:form.elements.email.value,profile:Object.fromEntries(new FormData(form))});await open(current.id);$('#user-edit-message').textContent='Cadastro atualizado.';await load()}catch(err){$('#user-edit-message').textContent=err.message}finally{lock(false)}};
$('#user-ban-toggle').onclick=async()=>{if(loading)return;const banned=!current.banned;if(!confirm(banned?'Banir este usuário e encerrar suas sessões? Ele não poderá entrar, pedir ou avaliar. Pedidos e avaliações existentes serão mantidos.':'Reativar este usuário? Ele poderá entrar novamente na conta.'))return;lock(true);try{await api('/api/admin/users/ban',{id:current.id,revision:current.revision,banned,reason:$('#user-ban-reason').value});await open(current.id);$('#user-edit-message').textContent=banned?'Usuário banido. Acesso bloqueado e sessões encerradas.':'Usuário reativado.';await load()}catch(e){$('#user-edit-message').textContent=e.message}finally{lock(false)}};
})();
